/* Bulletin Board: importance/tag labels & highlights */
.board-tag-high {
  background: #ffe5e5;
  color: #c8352a;
  border-radius: 999px;
  font-weight: 800;
  font-size: 13px;
  padding: 2px 11px;
}
.board-tag-average {
  background: #ede8fd;
  color: #5666b5;
  border-radius: 999px;
  font-weight: 800;
  font-size: 13px;
  padding: 2px 11px;
}
.board-tag-low {
  background: #e0fcf7;
  color: #096;
  border-radius: 999px;
  font-weight: 800;
  font-size: 13px;
  padding: 2px 11px;
}
.board-highlight {
  box-shadow: 0 6px 20px 0 rgba(220,70,60,0.11), 0 2px 10px 0 rgba(60,90,255,0.06);
  transition: box-shadow 0.12s;
}
